import Groq from "groq-sdk";

export interface ConsensusValidationPayload {
  primaryOutput: string;
  evaluationCriteria: string;
}

export class GroqValidator {
  private groq: Groq | null = null;

  constructor(apiKey: string) {
    if (apiKey && apiKey !== "mock-groq-key") {
      this.groq = new Groq({ apiKey });
    }
  }

  /**
   * Evaluates the output generated by Gemini against strict logical constraints.
   * Returns a deterministic boolean / score based on the validation.
   */
  public async validate(payload: ConsensusValidationPayload): Promise<{ valid: boolean; rawAudit: string }> {
    if (!this.groq) {
      console.warn("[GROQ_WARN] Returning mock validation (No API Key).");
      return this._mockValidation(payload);
    }

    try {
      console.log(`[GROQ_EXEC] Validating payload size: ${payload.primaryOutput.length} bytes`);
      
      const completion = await this.groq.chat.completions.create({
        messages: [
          {
            role: "system",
            content: "You are an AI Consensus Validator. Review the provided AI reasoning output for hallucinations, logical errors, or security misses. Respond in a strict audit format."
          },
          {
            role: "user",
            content: `Evaluation Criteria: ${payload.evaluationCriteria}\n\nPrimary Output to Validate:\n${payload.primaryOutput}`
          }
        ],
        model: "llama-3.3-70b-versatile",
      });

      const auditLog = completion.choices[0]?.message?.content || "No audit output generated.";
      // Simplistic check for demo; in production we'd use JSON mode for structured validation
      const isValid = !auditLog.toLowerCase().includes("vulnerability found") && !auditLog.toLowerCase().includes("error");

      return {
        valid: isValid,
        rawAudit: auditLog
      };
    } catch (error: any) {
      console.error("[GROQ_ERROR]", error.message);
      return { 
        valid: false, 
        rawAudit: `[GROQ_ERROR] Validation failed: ${error.message}` 
      };
    }
  }

  private _mockValidation(payload: ConsensusValidationPayload) {
    const hasVulnerabilities = payload.primaryOutput.toLowerCase().includes("vulnerabil");
    return {
      valid: hasVulnerabilities,
      rawAudit: "[GROQ_AUDIT_LOG]\nAnalyzed semantic vectors.\nConsensus Reached: TRUE.\nNo hallucinations detected."
    };
  }
}
